.sparkline {
  position: relative;
  inline-size: 100%;
  block-size: var(--sparkline-height);
  min-inline-size: var(--space-12);
  /* Local to this component: the three heights a trend is read at. */
  --sparkline-height: var(--space-8);
  /* Slot 1, the same colour a single-series chart takes everywhere else. */
  --sparkline-color: var(--chart-1);
}
.sparkline[data-size="sm"] { --sparkline-height: var(--space-6); }
.sparkline[data-size="lg"] { --sparkline-height: var(--space-12); }

.sparkline svg { display: block; inline-size: 100%; block-size: 100%; overflow: visible; }
[dir="rtl"] .sparkline svg { transform: scaleX(-1); }

.sparkline-line {
  fill: none;
  stroke: var(--sparkline-color);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.sparkline-area { fill: var(--sparkline-color); opacity: 0.12; stroke: none; }

.sparkline-point {
  position: absolute;
  inline-size: var(--space-2);
  block-size: var(--space-2);
  margin-block-start: calc(var(--space-2) / -2);
  /* No negative inline margin: the endpoint dot stays INSIDE the frame. Half a
   * dot hanging off the end is invisible in a padded card and clipped at the
   * edge of anything else, and the last point is the one the reader stands on. */
  border-radius: var(--radius-full);
  background: var(--sparkline-color);
  /* The ring is the surface the sparkline actually sits on, which is a card
   * (surfaces.json says so). In dark theme --background is the page, one tier
   * below the card, so the dot came with a dark halo on it. */
  box-shadow: 0 0 0 2px var(--card);
}

.sparkline[data-tone="neutral"] { --sparkline-color: var(--muted-foreground); }
/* -emphasis, not the fill: a sparkline is a 2px stroke, which SC 1.4.11
 * holds to 3:1, and the solid tones sit at 2.78-2.94 on a dark card. */
.sparkline[data-tone="success"] { --sparkline-color: var(--success-emphasis); }
.sparkline[data-tone="warning"] { --sparkline-color: var(--warning-emphasis); }
.sparkline[data-tone="danger"]  { --sparkline-color: var(--destructive-emphasis); }

/* In a card the chart takes the spare height. Cards in a row are the same
 * height (owner's rule, 23.08), so a card whose subject is a chart gets extra
 * room — and the honest place for it is the plot, not a band of white between
 * the plot and the footer. Its own height stays the floor. */
.card > .sparkline {
  flex: 1 1 auto;
  block-size: auto;
  min-block-size: var(--sparkline-height);
}

import "./Sparkline.css";
import { cn } from "../lib/cn";

type Tone = "neutral" | "primary" | "success" | "warning" | "danger";
type Size = "sm" | "md" | "lg";

type Props = {
  /** The series, oldest first. Two points is the minimum that has a shape. */
  values: number[];
  /** What the trend MEANS to this metric, and it does not follow the direction: revenue climbing
   *  is `success`, a queue climbing is `warning`, and the same rising line is both.
   */
  tone?: Tone;
  /** Fills the area under the line — for a card that carries only this one series. */
  area?: boolean;
  /** How much of the row it is allowed: `sm` beside a value in a stat, larger only when the
   *  shape itself is being read.
   */
  size?: Size;
  /** What the series measures. Given, the chart is an image to a screen reader;
   *  omitted, it is decoration beside a value that already says it. */
  label?: string;
  className?: string;
};

/* The drawing space. Width is normalised to 100 so the SVG can stretch to any
 * column (preserveAspectRatio="none"); the stroke is held even by
 * vector-effect, and the endpoint dot is a real element so stretching cannot
 * turn it into an ellipse. */
const W = 100;
const H = 32;
const PAD = 2;

function geometry(values: number[]) {
  const n = values.length;
  const min = Math.min(...values);
  const max = Math.max(...values);
  /* A SERIES THAT DID NOT MOVE IS DRAWN DOWN THE MIDDLE, not along the floor.
   *
   * With no span there is nothing to divide by, and the old `|| 1` put every
   * point at the bottom of the box — which reads as a value pinned at zero, the
   * one thing a flat series does not say. Found by its first test, 2026-09-03.
   * `flat` is carried rather than faked because the caller's numbers are fine;
   * it is the drawing space that has no opinion. */
  const flat = max === min;
  const span = max - min || 1;
  const step = n > 1 ? W / (n - 1) : 0;
  const points = values.map((v, i) => {
    const x = n > 1 ? i * step : W / 2;
    const y = flat ? H / 2 : PAD + (1 - (v - min) / span) * (H - PAD * 2);
    return [x, y] as const;
  });
  const line = points.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(2)} ${y.toFixed(2)}`).join(" ");
  const last = points[points.length - 1];
  return {
    line,
    area: `${line} L${W} ${H} L0 ${H} Z`,
    lastX: (last[0] / W) * 100,
    lastY: (last[1] / H) * 100,
  };
}

/** The shape of a number over time: a line with no axes, no grid and no
 *  tooltip — the trend part of a KPI card, not a chart. Reach for <Meter> when
 *  the value is judged against a target instead of against its own past. 
 *
 * Copy: the accessible label says what the trend is OF and over what, because
 * the shape alone is unreadable to anyone who cannot see it.
 */
export function Sparkline({ values, tone = "primary", area, size, label, className }: Props) {
  if (values.length < 2) return null;
  const g = geometry(values);

  return (
    <div
      className={cn("sparkline", className)}
      data-tone={tone}
      data-size={size}
      data-area={area ? "" : undefined}
      role={label ? "img" : "presentation"}
      aria-label={label}
    >
      <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" aria-hidden="true" focusable="false">
        {area && <path className="sparkline-area" d={g.area} />}
        <path className="sparkline-line" d={g.line} vectorEffect="non-scaling-stroke" />
      </svg>
      {/* Positioned from the END of the series, which is the inline end in both
          directions once the chart itself mirrors under [dir="rtl"]. */}
      <span
        className="sparkline-point"
        style={{ insetInlineEnd: `${100 - g.lastX}%`, insetBlockStart: `${g.lastY}%` }}
        aria-hidden="true"
      />
    </div>
  );
}
